const stickyVisualState=new Map();socket.on('state',next=>{if(next?.game!=='uno')return;const playerIds=new Set((next.players||[]).map(player=>player.id));for(const player of next.players||[]){const turns=Number(player.unoChaosStickyTurns)||0,previousTurns=stickyVisualState.get(player.id)||0;if(turns!==previousTurns){if(turns)stickyVisualState.set(player.id,turns);else stickyVisualState.delete(player.id);window.dispatchEvent(new CustomEvent('uno3d-sticky-state',{detail:{playerId:player.id,turnsRemaining:turns,active:turns>0,newlyApplied:!previousTurns&&turns>0}}))}}for(const playerId of [...stickyVisualState.keys()])if(!playerIds.has(playerId))stickyVisualState.delete(playerId)});
const forbiddenVisualState=new Map();let lastDoubleAttackBurst=null;socket.on('state',next=>{if(next?.game!=='uno')return;const entries=Array.isArray(next.unoChaosForbidden)?next.unoChaosForbidden:next.unoChaosForbidden?[next.unoChaosForbidden]:[],current=new Set();for(const entry of entries){const key=entry.id||`${entry.color}:${entry.ownerId}`,turns=entry.turnsRemaining??2,previous=forbiddenVisualState.get(key);current.add(key);if(!previous||previous.turns!==turns){forbiddenVisualState.set(key,{color:entry.color,turns});window.dispatchEvent(new CustomEvent('uno3d-forbidden-state',{detail:{id:key,color:entry.color,turnsRemaining:turns,active:true}}))}}for(const [key,value] of [...forbiddenVisualState])if(!current.has(key)){forbiddenVisualState.delete(key);window.dispatchEvent(new CustomEvent('uno3d-forbidden-state',{detail:{id:key,color:value.color,turnsRemaining:0,active:false}}))}const burst=next.unoChaosDoubleAttackBurst;if(burst?.id&&burst.id!==lastDoubleAttackBurst&&Date.now()-(burst.createdAt||0)<6000){lastDoubleAttackBurst=burst.id;window.dispatchEvent(new CustomEvent('uno3d-double-attack',{detail:burst}))}});
