const HUGO_NAMES={red:'Rojo',yellow:'Amarillo',green:'Verde',blue:'Azul'};
const HUGO_LABELS={draw2:'+2',reverse:'↺',skip:'⊘',wild:'★',wild4:'+4'};
const CHAOS_ICONS={mirror:'✦',shield:'⬡',lightning:'⚡',redirect:'➜',absorb:'◉',falseAlarm:'?',secondChance:'↺',explosiveSwap:'⇆',sticky:'✹',decoy:'♟',parasite:'🪲',tomato:'🍅',duel:'VS',carousel:'⟳',steal:'👻',bomb:'💣',forbid:'⛔',roulette:'✹',swap:'⇄',blackMarket:'🎴',freeze:'❄',colorThief:'🎨',sharedHand:'🤝',clone:'⧉',cheater:'🃏',doubleAttack:'×2',growingDraw:'+N',trapSteal:'🪝',rupture:'💥',sabotage:'🧨',cataclysm:'☄',redistribution:'⚖'};
