function unoCardHtml(card,clickable=false){if(card.unoAbsorbed)return `<button type="button" data-card-id="${card.id}" class="uno-card absorbed-template" disabled aria-label="Carta absorbida temporalmente"><small>ABSORBIDA</small><i class="uno-corner-top">+${Number(card.absorbedValue)||''}</i><b>◉</b><i class="uno-corner-bottom">◉</i><em>NO UTILIZABLE</em><span class="chaos-card-info" tabindex="0" data-tooltip="Carta temporal guardada por Absorción. No puede jugarse ni descartarse; desaparecerá al liberar la trampa." onclick="event.stopPropagation()">i</span></button>`;const chaos=Boolean(card.chaosType),trap=card.kind==='trap',alwaysCheater=card.chaosType==='cheater'&&state?.status==='playing',enabled=clickable||alwaysCheater,label=chaos?(CHAOS_ICONS[card.chaosType]||'✦'):card.type==='number'?card.value:HUGO_LABELS[card.type],wild=!card.color,action=chaos?`openChaosCard('${card.id}')`:`openUnoPlay('${card.id}')`,locked=state?.players?.find(player=>player.id===socket.id)?.unoChaosLockedCardId===card.id,interaction=enabled?`onclick="${action}"`:chaos?'aria-disabled="true"':'disabled',charges=card.chaosType==='cheater'?`<strong class="cheater-charge-mark">${card.chaosCharges??3}</strong>`:'';return `<button type="button" data-card-id="${card.id}" class="uno-card ${chaos?'chaos-card chaos-'+card.chaosType:card.color||'wild'} ${enabled?'playable':''} ${locked?'chaos-locked':''}" ${interaction}><small>${chaos?esc(card.name||'CAOS'):wild?'COMODÍN':HUGO_NAMES[card.color]}</small><i class="uno-corner-top">${label}</i><b>${label}</b><i class="uno-corner-bottom">${label}</i>${chaos?`<em>${trap?'TRAMPA':esc(card.kind||'magia')}</em><span class="chaos-card-info" tabindex="0" data-tooltip="${esc(`${card.name}: ${card.text||''}`)}" onclick="event.stopPropagation()" aria-label="Información de ${esc(card.name)}">i</span>`:''}${charges}${locked?'<strong class="chaos-lock-mark">PEGADA</strong>':''}</button>`}
const UNO_HAND_COLORS={red:0,yellow:1,green:2,blue:3};
function orderedUnoHand(hand=[]){const category=card=>card.unoAbsorbed?5:card.chaosType?(card.kind==='trap'?3:4):card.type==='number'?0:['draw2','reverse','skip'].includes(card.type)?1:['wild','wild4'].includes(card.type)?2:6;return hand.map((card,index)=>({card,index})).sort((left,right)=>{const leftCategory=category(left.card),rightCategory=category(right.card);if(leftCategory!==rightCategory)return leftCategory-rightCategory;if(leftCategory<=1){const color=(UNO_HAND_COLORS[left.card.color]??9)-(UNO_HAND_COLORS[right.card.color]??9);if(color)return color;if(left.card.type==='number'&&right.card.type==='number'){const value=Number(left.card.value)-Number(right.card.value);if(value)return value}const type=String(left.card.type).localeCompare(String(right.card.type),'es');if(type)return type}if(left.card.chaosType&&right.card.chaosType){const name=String(left.card.name||left.card.chaosType).localeCompare(String(right.card.name||right.card.chaosType),'es');if(name)return name}return left.index-right.index}).map(item=>item.card)}
