function isUnoCardPlayable(card){const me=state.players.find(player=>player.id===socket.id);if(card.chaosType||card.unoAbsorbed||me?.unoChaosLockedCardId===card.id||isUnoColorForbidden(card.color))return false;const top=state.unoDiscard?.at(-1);if(!top)return false;const sameNumber=card.type==='number'&&top.type==='number'&&Number(card.value)===Number(top.value);if(state.unoChaosGravity&&['wild','wild4'].includes(card.type))return false;if(state.unoChaosPeace&&['draw2','wild4'].includes(card.type))return false;if(state.unoDrawStack)return card.type==='draw2';if(card.type==='wild')return true;if(card.type==='wild4')return !state.hand.some(other=>other.id!==card.id&&other.color===state.unoColor&&!isUnoColorForbidden(other.color));if(state.unoChaosChromatic)return sameNumber;return card.color===state.unoColor||sameNumber||(card.type!=='number'&&card.type===top.type)}
