function openChaosGlossary(){const modal=$('#unoPlayModal'),active=[];if(state?.unoChaosForbidden?.length)active.push(`Colores prohibidos: ${state.unoChaosForbidden.map(rule=>HUGO_NAMES[rule.color]||rule.color).join(', ')}`);if(state?.unoChaosCursedNumber)active.push(`Número maldito: ${state.unoChaosCursedNumber.number}`);if(state?.unoChaosChromatic)active.push('Caos cromático: solo coincide el número');if(state?.unoChaosSecret)active.push(state.ownChaosSecretRule?`Regla secreta: ${state.ownChaosSecretRule}`:'Hay una regla secreta activa');for(const [key,name] of [['unoChaosFog','Niebla'],['unoChaosGravity','Gravedad'],['unoChaosInflation','Inflación'],['unoChaosPeace','Paz temporal'],['unoChaosOpenHands','Manos abiertas'],['unoChaosMagicTax','Impuesto mágico'],['unoChaosFragility','Fragilidad']])if(state?.[key])active.push(name);modal.dataset.composing='true';modal.hidden=false;modal.innerHTML=`<section class="uno-compose chaos-glossary"><button class="uno-modal-close" onclick="closeChaosCard()">×</button><small>CONSULTA SIN SALIR DE LA PARTIDA</small><h2>Glosario de HUGO Caos</h2>${active.length?`<div class="glossary-active"><b>ACTIVO AHORA</b>${active.map(text=>`<span>${esc(text)}</span>`).join('')}</div>`:''}<details open><summary>Prioridad de resolución</summary><ol><li>Se anuncia el ataque y su objetivo.</li><li>Escudo de premio.</li><li>Primera trampa compatible colocada boca abajo.</li><li>Redirecciones y nuevas defensas, en cadena.</li><li>Robo, intercambio o cancelación final.</li></ol><p>Mientras una elección, apuesta, duelo o reporte está pendiente, las demás acciones esperan en la cola.</p></details><details><summary>Eventos globales</summary><ul><li><b>Niebla:</b> oculta valores rivales una vuelta.</li><li><b>Gravedad:</b> bloquea comodines una vuelta.</li><li><b>Inflación:</b> suma 2 a cada ataque.</li><li><b>Paz temporal:</b> bloquea ataques una vuelta.</li><li><b>Manos abiertas:</b> revela las manos 5 segundos, salvo bajo Niebla.</li><li><b>Impuesto mágico:</b> cada magia agrega una carta normal.</li><li><b>Fragilidad:</b> rompe al final de la vuelta las trampas que no se activaron.</li></ul></details><details><summary>Reglas esenciales</summary><ul><li>Las cartas normales se juegan por color, número o símbolo.</li><li>Las mágicas y trampas no obligan a robar del mazo: puedes conservarlas.</li><li>Colocar o usar una carta Caos termina el turno, salvo Tramposo.</li><li>Debes anunciar HUGO antes de lanzar tu penúltima carta.</li></ul></details><details><summary>Trampas (${TRAP_CATALOG.length})</summary><div class="glossary-grid">${TRAP_CATALOG.map(([type,name,text])=>`<article><i>${CHAOS_ICONS[type]||'?'}</i><span><b>${esc(name)}</b><small>${esc(text)}</small></span></article>`).join('')}</div></details><details><summary>Cartas mágicas (${MAGIC_CATALOG.length})</summary><div class="glossary-grid">${MAGIC_CATALOG.map(([type,name,text])=>`<article><i>${CHAOS_ICONS[type]||'✦'}</i><span><b>${esc(name)}</b><small>${esc(text)}</small></span></article>`).join('')}</div></details></section>`}
