function openPortfolio(playerId){tradeTarget=state.players.find(p=>p.id===playerId);if(!tradeTarget)return;selectedOffer=null;$('#tradePlayerName').textContent=tradeTarget.name;$('#offerComposer').hidden=true;const entries=Object.entries(state.owners).filter(([,id])=>id===playerId);$('#tradeProperties').innerHTML=entries.length?entries.map(([position])=>{const t=state.board[position],development=state.buildings?.[position],houses=development?.houses||0,hotel=Boolean(development?.hotel),developmentIcons=hotel?'<div class="trade-development" aria-label="1 hotel"><i class="building-icon hotel-icon" title="1 hotel">H</i></div>':houses?`<div class="trade-development" aria-label="${houses} casas">${Array.from({length:houses},()=>'<i class="building-icon house-icon" title="Casa">⌂</i>').join('')}</div>`:'';return `<article class="trade-property" style="--group:${tradeColors[t.group||t.type]||'#176c69'}"><small>${t.type==='property'?'PAÍS':'PROPIEDAD ESPECIAL'}</small><h3>${esc(t.name)}</h3>${propertyPhoto(t,'trade-photo')}${developmentIcons}<strong>${money(t.price)}</strong><button onclick="chooseTradeProperty(${position})">Hacer oferta</button></article>`}).join(''):'<p>Este jugador todavía no tiene propiedades disponibles.</p>';$('#tradeModal').hidden=false}
function closeTrade(){$('#tradeModal').hidden=true;tradeTarget=null;selectedOffer=null}function cancelOffer(){selectedOffer=null;$('#offerComposer').hidden=true}
function chooseTradeProperty(position){selectedOffer={sellerId:tradeTarget.id,position};const property=state.board[position],owned=Object.entries(state.owners).filter(([,owner])=>owner===socket.id).map(([rawPosition])=>Number(rawPosition)),eligible=owned.filter(pos=>{const tile=state.board[pos];return !state.mortgages?.[pos]&&!(tile.group&&groupPositionsFor(pos).some(groupPos=>state.buildings?.[groupPos]))});$('#offerPropertyName').textContent=property.name;$('#offerAmount').min=0;$('#offerAmount').value=0;let choices=$('#offerPropertyChoices');if(!choices){choices=document.createElement('fieldset');choices.id='offerPropertyChoices';choices.className='offer-property-choices';$('#offerAmount').closest('label').before(choices)}choices.innerHTML=`<legend>Propiedades que entregas (opcional)</legend>${eligible.length?eligible.map(pos=>`<label><input type="checkbox" value="${pos}"><span>${esc(state.board[pos].name)}</span></label>`).join(''):'<small>No tienes propiedades libres de hipotecas y construcciones.</small>'}`;$('#offerComposer').hidden=false;$('#offerAmount').focus();$('#offerComposer').scrollIntoView({behavior:'smooth',block:'nearest'})}
function submitOffer(){if(!selectedOffer)return;const amount=Number($('#offerAmount').value||0),offeredPositions=[...document.querySelectorAll('#offerPropertyChoices input:checked')].map(input=>Number(input.value));socket.emit('makeTradeOffer',{...selectedOffer,amount,offeredPositions},result=>{if(!result?.ok)return toast(result?.message||'No se pudo enviar la oferta');toast('Oferta enviada');closeTrade()})}
