function renderOffers(){if(!state)return;const incoming=tradeOffers.filter(o=>o.sellerId===socket.id),outgoing=tradeOffers.filter(o=>o.buyerId===socket.id);$('#offersCount').textContent=incoming.length;$('#offersList').innerHTML=(incoming.length?`<h4>Recibidas</h4>${incoming.map(o=>`<article class="offer-item"><span>${esc(o.buyerName)} QUIERE RECIBIR</span><b>${esc(o.propertyName)}</b>${offerPaymentHtml(o)}<div><button onclick="respondOffer('${o.id}',true)">Aceptar</button><button class="secondary" onclick="respondOffer('${o.id}',false)">Rechazar</button></div></article>`).join('')}`:'')+(outgoing.length?`<h4>Enviadas</h4>${outgoing.map(o=>`<article class="offer-item"><span>ESPERANDO A ${esc(o.sellerName)}</span><b>${esc(o.propertyName)}</b>${offerPaymentHtml(o)}<button class="secondary cancel-sent-offer" onclick="cancelSentOffer('${o.id}')">Cancelar propuesta</button></article>`).join('')}`:'')+(!incoming.length&&!outgoing.length?'<p>No tienes ofertas pendientes.</p>':'')}
function respondOffer(id,accept){socket.emit('respondTradeOffer',{offerId:id,accept},result=>{if(!result?.ok)toast(result?.message||'La oferta ya no está disponible');else toast(accept?'Intercambio completado':'Oferta rechazada')})}
function cancelSentOffer(id){socket.emit('cancelTradeOffer',id,result=>toast(result?.ok?'Propuesta cancelada':result?.message||'La oferta ya no está disponible'))}
function shouldAnimateMove(a,b){if(!a||a.status!=='playing')return false;const old=a.players[a.turn],now=b.players.find(p=>p.id===old?.id);return old&&now&&!old.bankrupt&&!now.bankrupt&&old.position!==now.position&&((a.phase==='roll'&&b.dice)||['deport','card'].includes(b.moveMode))}
function shouldAnimateDice(a,b){if(!a||a.status!=='playing'||a.phase!=='roll'||!b.dice)return false;const roller=a.players[a.turn],currentVersion=b.players.find(player=>player.id===roller?.id);if(!roller||!currentVersion||roller.bankrupt||currentVersion.bankrupt)return false;return !a.dice||a.dice[0]!==b.dice[0]||a.dice[1]!==b.dice[1]||a.phase!==b.phase}
function flushDiceNotices(){queuedDiceNotices.splice(0).forEach(showGameToast)}
