const wait=ms=>new Promise(r=>setTimeout(r,ms));
function buildCube(el,value){const faces=[value,7-value,3,4,2,5];el.innerHTML=['front','back','right','left','top','bottom'].map((f,i)=>`<div class="face ${f}">${['','⚀','⚁','⚂','⚃','⚄','⚅'][faces[i]]}</div>`).join('')}
async function animateTurn(a,b){
  if(window.World3D?.ready){
    hideArrival();const old=a.players[a.turn],now=b.players.find(p=>p.id===old.id),rolled=shouldAnimateDice(a,b),moved=old.position!==now.position;if(rolled){GameAudio.play('diceRoll');await window.World3D.throwDice(b.dice);GameAudio.play('diceImpact')}let stepTimer;if(moved&&(b.moveMode!=='deport'||Number.isInteger(b.deportFrom))){GameAudio.play('step');stepTimer=setInterval(()=>GameAudio.play('step'),360)}if(b.moveMode==='deport'&&moved){if(Number.isInteger(b.deportFrom)){await window.World3D.movePlayer(now,old.position,b.deportFrom);clearInterval(stepTimer);await new Promise(resolve=>setTimeout(resolve,500))}GameAudio.play('deported');await window.World3D.sendToDeported(now,b.deportFrom??old.position)}else if(b.moveMode==='card'&&moved)await window.World3D.movePlayerBySteps(now,old.position,b.cardMoveSteps);else if(moved)await window.World3D.movePlayer(now,old.position,now.position);clearInterval(stepTimer);await window.World3D.resetCamera();animating=false;window.World3D.sync(state);renderGame();flushDiceNotices();return;
  }
  hideArrival();const stage=$('#boardStage'),scene=$('#diceScene');stage.classList.add('camera-dice');buildCube($('#cube1'),b.dice[0]);buildCube($('#cube2'),b.dice[1]);scene.hidden=false;requestAnimationFrame(()=>scene.classList.add('rolling'));await wait(1450);scene.classList.remove('rolling');scene.classList.add('result');await wait(700);scene.hidden=true;scene.classList.remove('result');stage.classList.remove('camera-dice');stage.classList.add('camera-follow');
  const old=a.players[a.turn],now=b.players.find(p=>p.id===old.id);if(old.position===now.position){animating=false;renderGame();flushDiceNotices();return}const board=$('#board'),destination=board.querySelector(`[data-pos="${now.position}"]`);stage.style.setProperty('--focus-x',`${(destination.offsetLeft+destination.offsetWidth/2)/board.offsetWidth*100}%`);stage.style.setProperty('--focus-y',`${(destination.offsetTop+destination.offsetHeight/2)/board.offsetHeight*100}%`);const ghost=document.createElement('div');ghost.className=`moving-token token-${now.token}`;ghost.style.setProperty('--token',now.color);ghost.innerHTML=`<span class="token-body"><b>${ICONS[now.token]}</b></span><span class="token-base"></span>`;board.appendChild(ghost);const origin=board.querySelector(`[data-pos="${old.position}"]`);ghost.style.left=`${origin.offsetLeft+origin.offsetWidth/2}px`;ghost.style.top=`${origin.offsetTop+origin.offsetHeight/2}px`;let pos=old.position;const steps=(now.position-old.position+40)%40;await wait(180);
  for(let n=0;n<steps;n++){pos=(pos+1)%40;const tile=board.querySelector(`[data-pos="${pos}"]`);ghost.style.left=`${tile.offsetLeft+tile.offsetWidth/2}px`;ghost.style.top=`${tile.offsetTop+tile.offsetHeight/2}px`;await wait(180)}
  ghost.classList.add('landed');board.querySelector(`[data-pos="${now.position}"]`)?.classList.add('landed');stage.classList.remove('camera-follow');stage.classList.add('camera-land');await wait(650);ghost.remove();stage.classList.remove('camera-land');animating=false;renderGame();flushDiceNotices();if(state.phase==='decision')showArrival();
}
function showArrival(){const t=state.board[state.pending.position],me=state.players.find(p=>p.id===socket.id),mine=state.players[state.turn]?.id===socket.id;$('#arrivalType').textContent=t.type==='property'?'NUEVO DESTINO':t.type==='transport'?'CONEXIÓN DE VIAJE':'SERVICIO';$('#arrivalName').textContent=t.name;$('#arrivalPrice').innerHTML=`<strong>$${t.price}</strong><small>PRECIO DE COMPRA</small>`;$('#arrivalText').textContent=mine?'Este lugar aún no tiene dueño. ¿Quieres añadirlo a tu colección?':'El viajero actual está decidiendo si compra este lugar.';$('#arrivalActions').innerHTML=mine?`<button onclick="socket.emit('buy');hideArrival()" ${me.money<t.price?'disabled':''}>Comprar destino</button><button class="secondary" onclick="socket.emit('skip');hideArrival()">Seguir viajando</button>`:'<span class="waiting">Esperando decisión…</span>';$('#arrival').hidden=false;requestAnimationFrame(()=>$('#arrival').classList.add('visible'))}
