$('.close-arrival').textContent='↘';$('.close-arrival').setAttribute('aria-label','Minimizar compra pendiente');$('.close-arrival').onclick=()=>minimizeRequiredModal($('#arrival'),'Compra pendiente',`${state.turn}:${state.pending?.position}`);
function decoratePropertyCards(me){if(!me)return;const countries=state.board.map((tile,position)=>({tile,position})).filter(({tile})=>tile.type==='property'),groupFirst=new Map();countries.forEach(({tile,position})=>{if(!groupFirst.has(tile.group))groupFirst.set(tile.group,position)});Object.entries(state.owners).filter(([,owner])=>owner===me.id).forEach(([rawPosition])=>{const position=Number(rawPosition),tile=state.board[position],card=$(`.deed-${position}`);if(!card)return;card.style.order=tile.group?(groupFirst.get(tile.group)||0):100+position;const groupPositions=tile.group?countries.filter(item=>item.tile.group===tile.group).map(item=>item.position):[],complete=groupPositions.length>1&&groupPositions.every(pos=>state.owners[pos]===me.id);card.classList.toggle('complete-group',complete);const development=state.buildings?.[position],band=card.querySelector('.deed-band');if(!band)return;const icons=development?.hotel?'<span class="building-icon hotel-icon" title="1 hotel">H</span>':Array.from({length:development?.houses||0},()=>'<span class="building-icon house-icon" title="Casa">⌂</span>').join('');band.innerHTML=`${complete?'<span class="complete-label">✓ GRUPO</span>':''}<span class="deed-buildings">${icons}</span>`})}
function decoratePlayerConnections(){if(!state)return;['#players>.player','#lobbyPlayers>.lobby-player'].forEach(selector=>document.querySelectorAll(selector).forEach((element,index)=>{const player=state.players[index];element.classList.toggle('disconnected',player?.connected===false);element.querySelector('.connection-status')?.remove();element.querySelector('.disconnect-actions')?.remove();if(player?.connected===false){const status=document.createElement('span');status.className='connection-status';status.textContent='DESCONECTADO';element.appendChild(status);if(state.host===socket.id&&!player.bankrupt){const ready=Date.now()>=(player.disconnectedAt||Date.now())+(state.settings?.disconnectGrace||30)*1000,actions=document.createElement('div');actions.className='disconnect-actions';actions.innerHTML=`${state.players[state.turn]?.id===player.id?`<button ${!ready?'disabled':''} onclick="skipDisconnected('${player.id}')">Saltar turno</button>`:''}<button class="expel-player" ${!ready?'disabled':''} onclick="expelDisconnected('${player.id}')">Expulsar</button>`;element.appendChild(actions)}}}))}
