function unoHostPanelHtml(){return `<section class="management-window host-panel-window uno-host-panel"><button class="management-close" onclick="$('#hostPanel').hidden=true">×</button><small>CONTROL DE SALA · HUGO</small><h2>Panel del anfitrión</h2><div class="host-status"><article><span>CÓDIGO</span><b>${esc(state.code)}</b><button onclick="navigator.clipboard.writeText('${state.code}');toast('Código copiado')">Copiar</button></article><article><span>ESTADO</span><b>${state.manualPaused?'Pausada':state.status==='lobby'?'En lobby':state.status==='finished'?'Finalizada':'En curso'}</b><small>${state.players.length} jugadores · Sin puntuación</small></article></div><div class="host-primary-actions">${state.status==='playing'?`<button onclick="socket.emit('toggleRoomPause',${!state.manualPaused})">${state.manualPaused?'Reanudar HUGO':'Pausar HUGO'}</button><button class="secondary" onclick="hostSkipTurn()">Forzar siguiente turno</button>`:''}<button class="secondary" onclick="restartSavedRoom()">Repartir una partida nueva</button></div><h3>Jugadores de HUGO</h3><div class="host-player-list">${state.players.map(player=>`<article><i style="background:${player.color}"></i><b>${esc(player.name)}</b><span>${player.connected?`${player.handCount??player.unoHand?.length??0} cartas`:'Desconectado'}</span>${player.id!==socket.id?`<button onclick="kickPlayerFromRoom('${player.id}')">Expulsar</button>`:'<small>ANFITRIÓN</small>'}</article>`).join('')}</div>${state.status==='playing'?`<h3>Herramientas de debug</h3><p class="setting-note">La cantidad admite de 1 a 50 cartas. Trampa y mágica usan cartas aleatorias del modo Caos.</p><div class="uno-debug-list">${state.players.filter(player=>!player.abandoned).map(player=>`<article><div><b>${esc(player.name)}</b><small>${player.handCount??0} cartas${state.players[state.turn]?.id===player.id?' · TURNO ACTUAL':''}</small></div><input id="debugAmount-${player.id}" type="number" min="1" max="50" value="1" aria-label="Cantidad para ${esc(player.name)}"><div class="uno-debug-actions"><button onclick="unoHostDebug('${player.id}','normal')">+ Normal</button><button onclick="unoHostDebug('${player.id}','trap')">+ Trampa</button><button onclick="unoHostDebug('${player.id}','magic')">+ Mágica</button><button class="secondary" onclick="unoHostDebug('${player.id}','remove')">− Cartas</button><button class="secondary" onclick="unoHostDebug('${player.id}','forceTurn')">Pasar turno aquí</button></div></article>`).join('')}</div>`:''}<div class="host-danger-zone"><button class="secondary" onclick="finishSavedRoom()" ${state.status==='finished'?'disabled':''}>Finalizar HUGO</button><button class="delete-room-button" onclick="deleteSavedRoom()">Eliminar sala</button></div></section>`}
function unoHostDebug(playerId,action){const input=document.getElementById(`debugAmount-${playerId}`),amount=Math.max(1,Math.min(50,Math.floor(Number(input?.value)||1))),selector=document.getElementById(`debug-${action}-${playerId}`),cardType=selector?.value||null;socket.emit('hostUnoDebug',{playerId,action,amount,cardType},result=>toast(result?.message||'No se pudo aplicar el debug.'))}
function openHostPanel(){const panel=$('#hostPanel'),settings=state.settings||{},rules=settings.rules||{},lobby=state.status==='lobby';panel.hidden=false;if(state.game==='uno'){panel.innerHTML=unoHostPanelHtml();return}panel.innerHTML=`<section class="management-window host-panel-window"><button class="management-close" onclick="$('#hostPanel').hidden=true">×</button><small>CONTROL DE SALA</small><h2>Panel del anfitrión</h2><div class="host-status"><article><span>CÓDIGO</span><b>${esc(state.code)}</b><button onclick="navigator.clipboard.writeText('${state.code}');toast('Código copiado')">Copiar</button></article><article><span>ESTADO</span><b>${state.manualPaused?'Pausada':state.status==='lobby'?'En lobby':state.status==='finished'?'Finalizada':'En curso'}</b><small>Guardado automático · ${state.lastSavedAt?new Date(state.lastSavedAt).toLocaleTimeString('es-MX'):'pendiente'}</small></article></div><div class="host-primary-actions">${state.status==='playing'?`<button onclick="socket.emit('toggleRoomPause',${!state.manualPaused})">${state.manualPaused?'Reanudar':'Pausar'}</button><button class="secondary" onclick="hostSkipTurn()">Saltar turno actual</button>`:''}<button class="secondary" onclick="restartSavedRoom()">Reiniciar partida</button></div><h3>Dinero inicial</h3><select class="initial-money-select" onchange="socket.emit('setInitialMoney',Number(this.value))" ${!lobby?'disabled':''}>${[100000,150000,200000,250000].map(amount=>`<option value="${amount}" ${settings.initialMoney===amount?'selected':''}>${money(amount)}</option>`).join('')}</select>${!lobby?'<p class="setting-note">El dinero inicial solo puede cambiarse en el lobby.</p>':''}<h3>Reglas opcionales</h3><div class="optional-rules">${[['salaryOnStart','Cobrar $20,000 al pasar por Salida'],['doubleRentFullGroup','Renta doble por grupo completo sin construir'],['extraTurnOnDoubles','Turno adicional al obtener dobles'],['tripleDoublesJail','Deportado con tres dobles consecutivos'],['allowExpropriation','Permitir cartas de Expropiación'],['allowPropertySwap','Permitir intercambio de propiedades']].map(([key,label])=>`<label><input type="checkbox" ${rules[key]!==false?'checked':''} ${!lobby?'disabled':''} onchange="socket.emit('setOptionalRule',{rule:'${key}',enabled:this.checked})"><span>${label}</span></label>`).join('')}</div><h3>Jugadores</h3><div class="host-player-list">${state.players.map(player=>`<article><i style="background:${player.color}"></i><b>${esc(player.name)}</b><span>${player.connected?'Conectado':'Desconectado'}</span>${player.id!==socket.id?`<button onclick="kickPlayerFromRoom('${player.id}')">Expulsar</button>`:'<small>ANFITRIÓN</small>'}</article>`).join('')}</div><div class="host-danger-zone"><button class="secondary" onclick="finishSavedRoom()" ${state.status==='finished'?'disabled':''}>Finalizar partida</button><button class="delete-room-button" onclick="deleteSavedRoom()">Eliminar sala</button></div></section>`}
function hostSkipTurn(){const message=state.game==='uno'?'¿Forzar el siguiente turno? Se cancelará cualquier robo o selección pendiente del jugador actual.':'¿Saltar el turno actual? Se cancelará cualquier decisión pendiente, salvo deudas obligatorias.';if(confirm(message))socket.emit('hostSkipCurrentTurn')}
function kickPlayerFromRoom(playerId){const player=state.players.find(item=>item.id===playerId);if(confirm(`¿Expulsar definitivamente a ${player?.name||'este jugador'}?`))socket.emit('kickPlayer',playerId)}
function restartSavedRoom(){const message=state.game==='uno'?'¿Preparar una partida nueva de HUGO? Se conservarán la sala, jugadores y chat, pero se recogerán todas las cartas.':'¿Reiniciar la partida? Se conservarán jugadores, chat, reglas y sala, pero se borrará todo el progreso del tablero.';if(confirm(message))socket.emit('restartRoom')}
function skipDisconnected(playerId){socket.emit('skipDisconnectedTurn',playerId)}
function expelDisconnected(playerId){const player=state.players.find(item=>item.id===playerId);if(confirm(`¿Retirar definitivamente a ${player?.name||'este jugador'}? Sus propiedades volverán al banco y no podrá regresar a la partida.`))socket.emit('expelDisconnectedPlayer',playerId)}
function finishSavedRoom(){if(confirm('¿Finalizar la partida? La sala, el chat y la bitácora seguirán guardados.'))socket.emit('finishRoom')}
function deleteSavedRoom(){if(confirm('¿Eliminar definitivamente esta sala? Esta acción borrará la partida, el chat y la bitácora para todos.'))socket.emit('deleteRoom')}
function renderSavedCards(me,mine){const cards=me?.cards||[],button=$('#savedCardsButton'),panel=$('#savedCardsPanel');button.hidden=!cards.length;button.innerHTML=`CARTAS <b>${cards.length}</b>`;if(!cards.length){panel.hidden=true;return}const canUse=mine&&['roll','end'].includes(state.phase)&&!me.jailed,definitions={passport:{text:'Sal de Deportado inmediatamente sin pagar multa.',label:'Usar pasaporte',event:'usePassport',enabled:mine&&state.phase==='roll'&&me.jailed},expropriation:{text:'Adquiere la propiedad que te falta para completar un grupo.',label:'Elegir propiedad',event:'useExpropriation',enabled:canUse},propertySwap:{text:'Intercambia una propiedad limpia con la de otro jugador.',label:'Preparar intercambio',event:'usePropertySwap',enabled:canUse},repairInsurance:{text:'Se utilizará automáticamente en tu próximo cobro de reparaciones.',label:'Protección automática',event:null,enabled:false},rentBoost:{text:me.rentBoost?'Tu siguiente renta ya está duplicada.':'Duplica la siguiente renta que cobres.',label:me.rentBoost?'Ya está activa':'Activar temporada alta',event:'useRentBoost',enabled:canUse&&!me.rentBoost}};$('#savedCardsList').innerHTML=cards.map(card=>{const definition=definitions[card.type]||{text:'Carta especial conservada.',label:'No disponible',enabled:false};return `<article class="saved-special-card ${card.type}"><small>CARTA CONSERVABLE</small><h4>${esc(card.title)}</h4><p>${definition.text}</p><button ${definition.event?`onclick="socket.emit('${definition.event}')"`:''} ${!definition.enabled?'disabled':''}>${definition.label}</button></article>`}).join('')}
function renderSpecialChoice(me){const modal=$('#specialChoiceModal'),choice=state.specialChoice;if(!choice){modal.hidden=true;return}const mine=choice.playerId===socket.id;modal.hidden=false;if(choice.type==='propertySwap'){modal.innerHTML=`<section class="choice-window swap-window"><small>INTERCAMBIO CULTURAL</small><h2>Intercambia propiedades</h2><p>Solo participan propiedades sin hipoteca ni construcciones. La carta se consume al confirmar.</p><div class="swap-selectors"><label>ENTREGAS<select id="swapOwn">${choice.ownOptions.map(option=>`<option value="${option.position}">${esc(option.name)}</option>`).join('')}</select></label><span>⇄</span><label>RECIBES<select id="swapTarget">${choice.targetOptions.map(option=>`<option value="${option.position}">${esc(option.name)} · ${esc(option.ownerName)}</option>`).join('')}</select></label></div>${mine?'<div class="management-actions"><button class="secondary" onclick="socket.emit(\'cancelSpecialChoice\')">Cancelar</button><button onclick="confirmPropertySwap()">Confirmar intercambio</button></div>':'<span class="waiting">El jugador está preparando un intercambio…</span>'}</section>`;return}modal.innerHTML=`<section class="choice-window"><small>COMPRA ESPECIAL</small><h2>Completa un grupo</h2><p>La carta se gastará únicamente cuando confirmes una propiedad.</p><div class="choice-properties">${choice.options.map(option=>`<button onclick="socket.emit('resolveExpropriation',${option.position})" ${!mine||me.money<option.cost?'disabled':''}><b>${esc(option.name)}</b><span>Propietario: ${esc(option.ownerName)}</span><strong>${money(option.cost)}</strong></button>`).join('')}</div>${mine?'<button class="secondary" onclick="socket.emit(\'cancelSpecialChoice\')">Cancelar</button>':'<span class="waiting">El jugador está eligiendo una propiedad…</span>'}</section>`}
function confirmPropertySwap(){socket.emit('resolvePropertySwap',{ownPosition:Number($('#swapOwn').value),targetPosition:Number($('#swapTarget').value)})}
let managedPosition=null;
function groupPositionsFor(position){const tile=state.board[position];return tile.group?state.board.map((item,index)=>({item,index})).filter(entry=>entry.item.group===tile.group).map(entry=>entry.index):[Number(position)]}
function propertyActionInfo(action,position,me=state.players.find(player=>player.id===socket.id)){position=Number(position);const tile=state.board[position],block=groupPositionsFor(position),levels=block.map(pos=>{const dev=state.buildings?.[pos];return dev?.hotel?5:dev?.houses||0}),level=levels[block.indexOf(position)],allOwned=block.every(pos=>state.owners[pos]===me?.id),mortgaged=block.some(pos=>state.mortgages?.[pos]);let allowed=true,reason='',delta=0,label='';if(action==='buyHouse'){label=`Construir casa en ${tile.name}`;delta=-(tile.houseCost||0);if(tile.type!=='property')reason='Esta propiedad no admite construcciones.';else if(!allOwned)reason='Necesitas poseer todas las propiedades del grupo.';else if(mortgaged)reason='Primero recupera todas las propiedades hipotecadas del grupo.';else if(level>=4)reason='Esta propiedad ya tiene cuatro casas; el siguiente paso es un hotel.';else if(level!==Math.min(...levels))reason='Debes construir uniformemente comenzando por la propiedad menos desarrollada.';else if(me.money<tile.houseCost)reason=`Te faltan ${money(tile.houseCost-me.money)}.`}else if(action==='buyHotel'){label=`Construir hotel en ${tile.name}`;delta=-(tile.hotelCost||0);if(tile.type!=='property')reason='Esta propiedad no admite construcciones.';else if(!allOwned)reason='Necesitas poseer todas las propiedades del grupo.';else if(mortgaged)reason='No puedes construir con una propiedad hipotecada en el grupo.';else if(level!==4)reason='Esta propiedad necesita exactamente cuatro casas.';else if(level!==Math.min(...levels))reason='Todas las propiedades deben estar desarrolladas uniformemente.';else if(me.money<tile.hotelCost)reason=`Te faltan ${money(tile.hotelCost-me.money)}.`}else if(action==='sellBuilding'){const dev=state.buildings?.[position];label=`Vender ${dev?.hotel?'hotel':'casa'} de ${tile.name}`;delta=dev?.hotel?Math.floor(tile.hotelCost/2):Math.floor((tile.houseCost||0)/2);if(!dev)reason='Esta propiedad no tiene construcciones.';else if(level!==Math.max(...levels))reason='Primero vende en la propiedad más desarrollada para mantener uniformidad.'}else if(action==='mortgageProperty'){label=`Hipotecar ${tile.name}`;delta=tile.mortgage||tile.price/2;if(state.mortgages?.[position])reason='Esta propiedad ya está hipotecada.';else if(block.some(pos=>(state.buildings?.[pos]?.houses||state.buildings?.[pos]?.hotel)))reason='Primero vende todas las construcciones del grupo.'}else if(action==='unmortgageProperty'){label=`Recuperar ${tile.name}`;delta=-Math.ceil(tile.price*.55);if(!state.mortgages?.[position])reason='Esta propiedad no está hipotecada.';else if(me.money<Math.abs(delta))reason=`Te faltan ${money(Math.abs(delta)-me.money)}.`}allowed=!reason;return{action,position,tile,allowed,reason,delta,label,before:me?.money||0,after:(me?.money||0)+delta}}
function enhancePropertyManagement(me){if(!me)return;Object.entries(state.owners).filter(([,owner])=>owner===me.id).forEach(([rawPosition])=>{const position=Number(rawPosition),card=$(`.deed-${position}`),tile=state.board[position];if(!card)return;card.querySelectorAll('.building-actions button').forEach(button=>{const action=button.textContent.includes('Casa')?'buyHouse':button.textContent.includes('Hotel')?'buyHotel':'sellBuilding',info=propertyActionInfo(action,position,me);button.onclick=()=>requestPropertyAction(action,position);button.disabled=!info.allowed;button.title=info.reason});const mortgage=card.querySelector('.mortgage-card-button'),mortgageAction=state.mortgages?.[position]?'unmortgageProperty':'mortgageProperty',mortgageInfo=propertyActionInfo(mortgageAction,position,me);mortgage.onclick=()=>requestPropertyAction(mortgageAction,position);mortgage.disabled=!mortgageInfo.allowed;mortgage.title=mortgageInfo.reason;if(tile.type==='property'){const houseInfo=propertyActionInfo('buyHouse',position,me),status=document.createElement('p');status.className=`construction-status ${houseInfo.allowed?'ready':'blocked'}`;status.textContent=houseInfo.allowed?'Listo para construir':houseInfo.reason;card.appendChild(status)}const manage=document.createElement('button');manage.className='manage-group-button';manage.textContent=tile.group?'Ver grupo':'Administrar';manage.onclick=()=>openGroupManager(position);card.appendChild(manage)});if(managedPosition!==null&&!$('#managementModal').hidden)openGroupManager(managedPosition)}
function requestPropertyAction(action,position){const info=propertyActionInfo(action,position);if(!info.allowed)return toast(info.reason);const sign=info.delta>=0?'+':'−',modal=$('#financeConfirm');modal.hidden=false;modal.innerHTML=`<section class="management-window confirm-window"><small>CONFIRMAR OPERACIÓN</small><h2>${esc(info.label)}</h2><div class="money-summary"><div><span>Saldo actual</span><b>${money(info.before)}</b></div><div><span>Movimiento</span><b class="${info.delta>=0?'income':'expense'}">${sign}${money(Math.abs(info.delta))}</b></div><div><span>Saldo final</span><b>${money(info.after)}</b></div></div><p>${info.action==='mortgageProperty'?'La propiedad dejará de cobrar renta hasta recuperarla.':info.action==='sellBuilding'?'El banco devuelve la mitad del costo de construcción.':'La operación se aplicará inmediatamente.'}</p><div class="management-actions"><button class="secondary" onclick="$('#financeConfirm').hidden=true">Cancelar</button><button onclick="confirmPropertyAction('${info.action}',${info.position})">Confirmar</button></div></section>`}
function confirmPropertyAction(action,position){$('#financeConfirm').hidden=true;socket.emit(action,position)}
function closeGroupManager(){managedPosition=null;$('#managementModal').hidden=true}
function openGroupManager(position){managedPosition=Number(position);const me=state.players.find(player=>player.id===socket.id),positions=groupPositionsFor(managedPosition),tile=state.board[managedPosition],complete=positions.every(pos=>state.owners[pos]===me.id),modal=$('#managementModal');modal.hidden=false;modal.innerHTML=`<section class="management-window"><button class="management-close" onclick="closeGroupManager()">×</button><small>ADMINISTRACIÓN DE PATRIMONIO</small><h2>${tile.group?'Grupo completo':'Propiedad especial'}</h2><p class="group-overview ${complete?'complete':'incomplete'}">${complete?'✓ Posees todo el grupo y puedes desarrollarlo.':'Te faltan propiedades para poder construir.'}</p><div class="group-property-list">${positions.map(pos=>{const item=state.board[pos],ownerId=state.owners[pos],ownerPlayer=state.players.find(player=>player.id===ownerId),owned=ownerId===me.id,dev=state.buildings?.[pos],developmentIcons=dev?.hotel?'<span class="group-development"><i class="building-icon hotel-icon" title="1 hotel">H</i></span>':dev?.houses?`<span class="group-development">${Array.from({length:dev.houses},()=>'<i class="building-icon house-icon" title="Casa">⌂</i>').join('')}</span>`:'',house=propertyActionInfo('buyHouse',pos,me),hotel=propertyActionInfo('buyHotel',pos,me),sell=propertyActionInfo('sellBuilding',pos,me),mortgageAction=state.mortgages?.[pos]?'unmortgageProperty':'mortgageProperty',mortgage=propertyActionInfo(mortgageAction,pos,me),ownerColor=ownerPlayer?.color||'#8e928e',ownerText=owned?`${state.mortgages?.[pos]?'HIPOTECADA · ':''}Tu propiedad ${developmentIcons}`:ownerPlayer?`Propietario: ${esc(ownerPlayer.name)} ${developmentIcons}`:'DISPONIBLE EN EL BANCO',ownership=ownerPlayer?`<b class="group-owner"><i></i>${ownerText}</b>`:ownerText;return `<article class="group-property ${owned?'owned':ownerPlayer?'other-owned':'missing'}" style="--owner-color:${ownerColor}"><span>${ownership}</span><h3>${esc(item.name)}</h3>${owned?`<div class="group-actions">${item.type==='property'?`<button onclick="requestPropertyAction('buyHouse',${pos})" ${!house.allowed?'disabled':''} title="${esc(house.reason)}">Casa ${money(item.houseCost)}</button><button onclick="requestPropertyAction('buyHotel',${pos})" ${!hotel.allowed?'disabled':''} title="${esc(hotel.reason)}">Hotel ${money(item.hotelCost)}</button><button class="secondary" onclick="requestPropertyAction('sellBuilding',${pos})" ${!sell.allowed?'disabled':''} title="${esc(sell.reason)}">Vender</button>`:''}<button class="mortgage-action" onclick="requestPropertyAction('${mortgageAction}',${pos})" ${!mortgage.allowed?'disabled':''} title="${esc(mortgage.reason)}">${state.mortgages?.[pos]?'Recuperar':'Hipotecar'} ${money(Math.abs(mortgage.delta))}</button></div><p class="action-reason">${house.allowed?'Puedes agregar una casa.':esc(house.reason)}</p>`:''}</article>`}).join('')}</div></section>`}
function enhanceDebtMortgageActions(){const modal=$('#debtModal');if(modal.hidden)return;const heading=modal.querySelector('.debt-window>h3'),help=modal.querySelector('.debt-help');if(heading)heading.textContent='Vende casas u hoteles, o hipoteca';if(help)help.textContent='Puedes vender las construcciones una por una. También puedes hipotecar directamente: se liquidarán primero todas las construcciones del grupo y conservarás la propiedad para recuperarla después.';modal.querySelectorAll('.debt-assets button').forEach(button=>{const mortgageMatch=button.getAttribute('onclick')?.match(/mortgageProperty',(\d+)/),buildingMatch=button.getAttribute('onclick')?.match(/sellBuilding',(\d+)/);if(mortgageMatch){const position=Number(mortgageMatch[1]);button.onclick=()=>requestPropertyAction('mortgageProperty',position);return}if(!buildingMatch)return;const position=Number(buildingMatch[1]),tile=state.board[position],mortgageValue=Math.floor(tile.mortgage||tile.price/2),group=groupPositionsFor(position),constructionValue=group.reduce((sum,pos)=>{const item=state.board[pos],development=state.buildings?.[pos];if(!development)return sum;return sum+(development.hotel?Math.floor(item.hotelCost/2)+4*Math.floor(item.houseCost/2):(development.houses||0)*Math.floor(item.houseCost/2))},0),direct=document.createElement('button');direct.className='debt-asset mortgage-direct';direct.innerHTML=`<b>${esc(tile.name)}</b><small>Hipotecar directo</small><span>+${money(mortgageValue+constructionValue)}</span><em>Incluye liquidar construcciones del grupo</em>`;direct.onclick=()=>requestDebtMortgage(position,mortgageValue,constructionValue);button.after(direct)})}
function requestDebtMortgage(position,mortgageValue,constructionValue){const tile=state.board[position],me=state.players.find(player=>player.id===socket.id),total=mortgageValue+constructionValue,modal=$('#financeConfirm');modal.hidden=false;modal.innerHTML=`<section class="management-window confirm-window"><small>HIPOTECA PARA CUBRIR DEUDA</small><h2>Hipotecar ${esc(tile.name)}</h2><div class="money-summary"><div><span>Construcciones</span><b class="income">+${money(constructionValue)}</b></div><div><span>Hipoteca</span><b class="income">+${money(mortgageValue)}</b></div><div><span>Saldo final</span><b>${money(me.money+total)}</b></div></div><p>Se venderán todas las casas y hoteles del grupo. La escritura seguirá siendo tuya y podrás recuperar esta propiedad pagando la hipoteca después.</p><div class="management-actions"><button class="secondary" onclick="$('#financeConfirm').hidden=true">Cancelar</button><button onclick="confirmDebtMortgage(${position})">Liquidar e hipotecar</button></div></section>`}
function confirmDebtMortgage(position){$('#financeConfirm').hidden=true;socket.emit('mortgagePropertyForDebt',position)}
function renderFinalResults(){const modal=$('#resultsModal'),button=$('#resultsButton'),results=state.finalResults;if(state.status!=='finished'||!results?.length){modal.hidden=true;button.hidden=true;if(state.status==='lobby'){celebratedRoom=null;clearConfetti()}return}button.hidden=false;const leader=(selector)=>[...results].sort((a,b)=>selector(b)-selector(a))[0],rentLeader=leader(item=>item.stats.rentCollected),travelLeader=leader(item=>item.stats.spacesTraveled),debtLeader=leader(item=>item.stats.peakDebt),builderLeader=leader(item=>item.stats.housesBuilt+item.stats.hotelsBuilt);modal.innerHTML=`<section class="results-window"><button class="results-close" onclick="$('#resultsModal').hidden=true">×</button><div class="victory-crown">♛</div><small>${state.winner?'CAMPEÓN MUNDIAL':'PARTIDA FINALIZADA'}</small><h1>${esc(state.winner||results[0].name)}</h1><p>${state.winner?'Es la última persona solvente de la vuelta al mundo.':'Clasificación calculada por patrimonio neto.'}</p><div class="fun-awards"><article>💰 <span>Magnate de rentas</span><b>${esc(rentLeader.name)}</b><small>${money(rentLeader.stats.rentCollected)}</small></article><article>✈ <span>Más viajero</span><b>${esc(travelLeader.name)}</b><small>${travelLeader.stats.spacesTraveled} casillas · ${travelLeader.stats.laps} vueltas</small></article><article>📉 <span>Mayor deuda</span><b>${esc(debtLeader.name)}</b><small>${money(debtLeader.stats.peakDebt)}</small></article><article>🏨 <span>Gran constructor</span><b>${esc(builderLeader.name)}</b><small>${builderLeader.stats.housesBuilt} casas · ${builderLeader.stats.hotelsBuilt} hoteles</small></article></div><div class="final-ranking">${results.map(item=>`<article class="ranking-row ${item.id===state.winnerId?'champion':''}" style="--rank-color:${item.color}"><strong class="rank-number">${item.rank}</strong><div class="rank-player"><b>${esc(item.name)}</b><span>${item.bankrupt?'En bancarrota':item.properties+' propiedades'}</span></div><div><span>Efectivo</span><b>${money(item.cash)}</b></div><div><span>Propiedades</span><b>${money(item.propertyValue)}</b></div><div><span>Construcciones</span><b>${money(item.constructionValue)}</b></div><div><span>Deuda</span><b>−${money(item.debt)}</b></div><strong class="net-worth">${money(item.netWorth)}</strong></article>`).join('')}</div></section>`;if(celebratedRoom!==state.code){celebratedRoom=state.code;modal.hidden=false;launchConfetti();if(state.winnerId&&window.World3D?.celebrateWinner)window.World3D.celebrateWinner(state.winnerId)}}
function clearConfetti(){document.querySelectorAll('.confetti-layer').forEach(layer=>layer.remove())}
function launchConfetti(){clearConfetti();const layer=document.createElement('div');layer.className='confetti-layer';for(let index=0;index<90;index++){const piece=document.createElement('i');piece.style.setProperty('--x',`${Math.random()*100}vw`);piece.style.setProperty('--delay',`${Math.random()*3}s`);piece.style.setProperty('--duration',`${2.7+Math.random()*2.2}s`);piece.style.setProperty('--confetti',`hsl(${Math.random()*360} 82% 58%)`);layer.appendChild(piece)}document.body.appendChild(layer)}
